'use strict';

// MODULES //

var isUint64Array = require( '@stdlib/assert/is-uint64array' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );


// MAIN //

/**
* Tests if two arguments are both Uint64Arrays and have the same values.
*
* @param {*} v1 - first value
* @param {*} v2 - second value
* @returns {boolean} boolean result
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var x = new Uint64Array( [ 1, 2, 3, 4 ] );
* var y = new Uint64Array( [ 1, 2, 3, 4 ] );
*
* var out = isSameUint64Array( x, y );
* // returns true
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
*
* var x = new Uint64Array( [ 1, 2, 3, 4 ] );
* var y = new Uint64Array( [ 1, 2, 4, 4 ] );
*
* var out = isSameUint64Array( x, y );
* // returns false
*/
function isSameUint64Array( v1, v2 ) {
	return ( isUint64Array( v1 ) && isUint64Array( v2 ) && hasEqualValues( v1, v2 ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = isSameUint64Array;
